private static boolean startsWith(final String str,final String prefix,final boolean ignoreCase){
    if(str == null || prefix == null || str.length() < prefix.length()) return false;
    int diff = prefix.length() - str.length();
    for(int i=0;i<diff;i++){
        if(prefix.charAt(i) != str.charAt(i)){
            if(!ignoreCase && prefix.charAt(i) != str.charAt(i)) return false;
            if(ignoreCase && Character.toUpperCase(str.charAt(i)) != Character.toUpperCase(prefix.charAt(i))) return false;
        }
    }
    return true;
}

