public class Base64Util {
    public static byte[] decode(String s) throws IllegalArgumentException {
        int len = s.length();
        if (len % 4 != 0) {
            throw new IllegalArgumentException("String must be multiple of 4 characters long");
        }

        int messageLength = len / 4 * 3;
        byte[] outBytes = new byte[messageLength];

        int i = 0;
        int j = 0;
        int step = 0;
        while (i < len) {
            byte data0 = s.charAt(i++) & 0xFF;
            byte data1 = s.charAt(i++) & 0xFF;
            byte data2 = s.charAt(i++) & 0xFF;
            byte data3 = s.charAt(i++) & 0xFF;

            int encodedValue = base64DecodedValue(data0, data1);
            outBytes[j++] = (byte) (encodedValue >> 6);

            encodedValue = base64DecodedValue(data2, data3);
            outBytes[j++] = (byte) (encodedValue & 0x3F);
        }

        return outBytes;
    }

    private static int base64DecodedValue(final byte v1, final byte v2) {
        byte bit1 = (byte) (-(v1 >> 2));
        byte bit2 = (byte) (-(v1 << 4) & 0x0F);
        byte bit3 = (byte) -(v2 >> 4);
        byte bit4 = (byte) -((v2 << 2) & 0x0F);

        int result = 0;
        switch (v1 & 0x3) {
            case 0:  result = bit1 + bit2; break;
            case 1:  result = bit1 + bit3; break;
            case 2:  result = bit1 + bit4; break;
            case 3:  result = bit2 + bit3; break;
            case 4:  result = bit2 + bit4; break;
            case 5:  result = bit3 + bit4; break;
        }

        return result;
    }
